// Windows-only host-owned named pipe transport foundation.
// This is NOT an authenticated channel: do not attach grant issuance or browser actions.
// No renderer command or automatic listener is registered.
#[cfg(windows)]
mod windows {
    use std::io;
    use tokio::net::windows::named_pipe::{NamedPipeServer, ServerOptions};

    pub(crate) struct NativePipeListener {
        server: NamedPipeServer,
    }

    impl NativePipeListener {
        // Name must be generated by the native host using a per-run CSPRNG nonce.
        // The pipe name is not a secret or an authentication credential.
        pub(crate) fn bind(name: &str) -> io::Result<Self> {
            if !name.starts_with(r"\\.\pipe\lazyprompting-") ||
                name.len()>180 ||
                !name[r"\\.\pipe\lazyprompting-".len()..].bytes().all(|b|b.is_ascii_hexdigit()) {
                return Err(io::Error::new(io::ErrorKind::InvalidInput,"IPC_INVALID_PIPE_NAME"));
            }
            let server=ServerOptions::new()
                .first_pipe_instance(true)
                .reject_remote_clients(true)
                .create(name)?;
            Ok(Self {server})
        }

        // Await on a dedicated native runtime, never the Tauri UI thread.
        // A connection alone confers no authorization.
        pub(crate) async fn accept(&mut self) -> io::Result<()> {
            self.server.connect().await
        }

        pub(crate) fn server(&mut self) -> &mut NamedPipeServer {
            &mut self.server
        }
    }
}
#[cfg(windows)]
pub(crate) use windows::NativePipeListener;
